import{_ as o,l,o as e,c as n,v as i,p as s,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"背面供电 BSPDN","description":"","frontmatter":{"title":"背面供电 BSPDN","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/backside-power.md","filePath":"litho/backside-power.md","lastUpdated":1789023840000}'),E={name:"litho/backside-power.md"};function B(c,a,A,P,D,m){const t=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=i('<h1 id="背面供电-bspdn" tabindex="-1">背面供电 BSPDN <a class="header-anchor" href="#背面供电-bspdn" aria-label="Permalink to &quot;背面供电 BSPDN&quot;">​</a></h1><div class="epigraph"><p>正面金属栈同时背电流和信号时，供电孔先把布线资源吃光；把电源改到底面，是为给信号让出节距，不是再加一层装饰金属。</p><footer>—— 对照 Intel PowerVia 与 imec BSPDN 的公开演示与展望</footer></div><p><a href="/litho/nanosheet-spacing">上一课</a>把 GAA 的垂直片缝和横向节距拆开。缺口是：再紧的 CPP 与片宽，正面仍要走电源轨和信号。本课钉背面供电（backside power delivery network, BSPDN）。互补 FET 如何把 N/P 再堆一层，留给<a href="/litho/cfet">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准单元顶部的电源轨占掉最密金属资源，via 到晶体管的路径与信号争抢。<a href="/litho/beol-euv">后道 EUV</a> 把最密 Mx 做出来，供电网格仍在同一面抢密度、抢 IR drop。缩放继续，正面 PDN 成为布线墙，而不是光刻分辨率墙。</p><p>BSPDN 把电源/地改到晶圆背面：埋入式电源轨或纳米通孔把电流从背面金属送到器件，正面留给信号。Intel 公开的 PowerVia、imec 的 BSPDN 叙述走同一家族：背面金属 + 穿到正面器件的连接。缺口是集成与对准，不是再讲一遍片缝填充。</p><h3 id="背面不是「再做一次-beol」那么轻" tabindex="-1">背面不是「再做一次 BEOL」那么轻 <a class="header-anchor" href="#背面不是「再做一次-beol」那么轻" aria-label="Permalink to &quot;背面不是「再做一次 BEOL」那么轻&quot;">​</a></h3><p>要减薄、键合或直接在背面做金属，晶圆变薄后的翘曲、对准、缺陷与热，全部进套刻预算。电源 via 必须打中埋轨或接触，而不打穿沟道。这是新的光刻/对准层，不是把正面 Mx 配方镜像。</p><p><span class="marginnote">PowerVia、BSPDN、buried power rail 是各家对同一族的公开名称，细节（先轨后通孔、键合次序）不同。写课用「背面 PDN + 到器件的连接」，不要把商标当代数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>公开路径大致是：正面做完器件与部分互连 →（埋轨若在正面中段）→ 减薄露出连接点 → 背面金属网格 → 与封装或凸点衔接。光刻要管：埋轨开口、nano-TSV / via-to-rail、背面金属节距（通常松于最密正面信号，但仍要套刻到器件栅格）。对准策略从正面标记翻到背面，SPM 与红外对准成为一等设备问题。</p><p>电源完整性：背面网格可以更粗、更厚，IR drop 与电迁移从正面最密线转出。信号层得以放松拥塞，这是 DTCO 收益，用布线资源换，不是用 DIBL 数字换。</p><h3 id="与-gaa-的耦合" tabindex="-1">与 GAA 的耦合 <a class="header-anchor" href="#与-gaa-的耦合" aria-label="Permalink to &quot;与 GAA 的耦合&quot;">​</a></h3><p>纳米片接触已经挤。背面供电把电源 via 从顶部移走，给接触和信号 via 让位，GAA 的 Weff 档才有地方接出来。没有 BSPDN，GAA 的静电学收益更容易被正面供电孔吃掉——上一课的间距课在电路上还没闭环。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>正面最密层从「信号+电源」变成「以信号为主」，有效布线轨道增加。代价是晶圆变薄后的热机械：扫描时的卡盘、键合应力、背面金属与硅的热失配，都会进 <a href="/litho/wafer-thermal-overlay">晶圆热套刻</a>。良率学习曲线按新缺陷模式计：漏电到衬底、via 未打中、减薄损伤。</p><p>封装侧：背面已是电源面，与衬底凸点、中介层的接口要重画。这与 Chiplet 课衔接，但本课不把封装当 BSPDN 的替代。</p><p><span class="marginnote">读公开演示时区分：已宣布的产品路径、风险试产、实验室截面。把实验室背面网格写进当前节点功耗模型会高估可交货频率。</span></p>',18)),(e(),s(h,null,{default:r(()=>[d(t,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20FEOL%5B%22GAA%20%E5%99%A8%E4%BB%B6%22%5D%20--%3E%20BPR%5B%22%E5%9F%8B%E8%BD%A8%E6%88%96%E6%8E%A5%E8%A7%A6%22%5D%0A%20%20BPR%20--%3E%20TSV%5B%22%E5%88%B0%E8%83%8C%E9%9D%A2%E7%9A%84%20via%22%5D%0A%20%20TSV%20--%3E%20BPDN%5B%22%E8%83%8C%E9%9D%A2%E7%94%B5%E6%BA%90%E7%BD%91%E6%A0%BC%22%5D%0A%20%20FEOL%20--%3E%20SIG%5B%22%E6%AD%A3%E9%9D%A2%E4%BF%A1%E5%8F%B7%E9%87%91%E5%B1%9E%22%5D%0A%20%20BPDN%20--%3E%20IR%5B%22IR%20drop%20%E4%BB%8E%E6%AD%A3%E9%9D%A2%E6%9C%80%E5%AF%86%E5%B1%82%E8%BF%81%E5%87%BA%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CFET 堆叠，也不给未公开的 via 直径。不要发明 Intel 或 imec 的层数表。减薄后的晶圆刚度下降，扫描加速度与卡盘夹持会改 overlay 模型，必须回到热套刻与吸盘课一起看。后课默认：先进逻辑的供电可以在背面，正面最密层主要为信号服务。</p><p>引用 Intel PowerVia 与 imec BSPDN 公开材料。</p><p><span class="marginnote">背面供电不降低 EUV 层的物理需要，它改变层的<strong>用途</strong>。最密信号仍可能是 EUV。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BSPDN 把电源移到背面，把正面最密层还给信号。</li><li>新光刻项是埋轨、到背面的 via 和薄晶圆对准，不是镜像 Mx。</li><li>与 GAA 耦合：接触与供电不再在同一面挤。</li><li>热机械与减薄缺陷进入套刻和良率。</li><li>背面网格通常松于最密正面信号，但仍必须套刻到器件栅格。</li><li>出处：Intel PowerVia；imec BSPDN 公开论述。</li></ul>',6))])}const S=o(E,[["render",B]]);export{f as __pageData,S as default};
